import { addDays, ageFrom, animalStatuses, branchCodes, branches, caseInfo, dayLabel, doseOptions, fmt, isAccredited, isSale, longDate, money, municipalities, nextRegistryFor, protocolOf, protocols, refundCutoff, refundEligible, scheduleDates, seriesStart, suffixes, today, vaccineBrands, vaccinatorNames, visitNeedsPay, visitPaid, withName } from '../data'
