const inB=(branch,b)=>branch==='All branches'||b===branch
const scope=(items,branch)=>items.filter(x=>inB(branch,x.branch))
const encBranch=e=>e.transferredTo||e.branch
const initials=n=>(n||'?').split(' ').map(x=>x[0]).join('').slice(0,2)
const byDate=(a,b)=>b.date.localeCompare(a.date)
const latestOf=(encounters,pid)=>encounters.filter(e=>e.patientId===pid).sort(byDate)[0]
export const flagsOf=p=>[p.senior&&'Senior',p.pwd&&'PWD',p.vetmed&&'Vetmed',p.philhealth&&'PhilHealth'].filter(Boolean)
const nowTime=()=>new Date().toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'})
const staffOf=list=>(list||[]).filter(e=>['Nurse / Staff','PO / PhilHealth Officer'].includes(e.role)).map(e=>e.name)
const blankEncounter=(p,branch,registry)=>({id:'ENC-'+Date.now().toString().slice(-6),registry,patientId:p.id,branch,date:today,time:nowTime(),chief:'',animal:'Dog',animalOther:'',biteType:'Bite',pet:true,vaccinated:false,stray:false,owned:true,owner:'',biteDate:today,biteTime:'',side:'L',site:'',place:'',washed:true,tandok:false,wound:[],category:'',booster:false,preExp:false,vaccine:'PVRV',brand:'Bioshoot',regimen:'ID',history:{iddm:false,kidney:false,dialysis:false,cancer:false,allergy:false,steroids:false,insulin:false,others:''},bp:'',weight:'',temp:'',consent:false,consentBy:p.guardian?p.guardian.split(' (')[0]:p.name,tt:{given:false,date:'',time:'',refused:false,withPrevious:false},rig:'',erig:{brand:'',date:'',skinTime:'',skinResult:'',weight:'',infiltration:false,ml:'',refused:false},pepEligible:true,stopAfter:null,animalStatus:'Alive',progress:{healthy:false,healed:false,others:''},doctor:'',remark:'',transferredTo:'',died:false,rer:false,billing:''})
const blankPatient=branch=>({last:'',first:'',middle:'',suffix:'',birthday:'',sex:'',contact:'',address:'',municipality:'Guimba',municipalityOther:'',guardian:'',senior:false,pwd:false,vetmed:false,philhealth:false,branch})
const nameReady=f=>f.last.trim()&&f.first.trim()&&f.birthday&&f.sex&&(f.contact||'').trim()
const normalized=v=>(v||'').trim().toLowerCase()
const samePerson=(a,b)=>normalized(a.last)===normalized(b.last)&&normalized(a.first)===normalized(b.first)&&normalized(a.middle)===normalized(b.middle)&&a.birthday===b.birthday
export function consume(inventory,item,branch,uses=1,batch){const pool=inventory.filter(x=>x.item===item&&x.branch===branch&&x.expiry>=today&&x.stock>0);const line=batch?pool.find(x=>x.batch===batch):pool.slice().sort((a,b)=>a.expiry.localeCompare(b.expiry))[0];if(!line)return {error:'No usable '+item+' stock at '+branch};const capacity=line.usesPerVial||0,total=capacity?(line.uses||0)+uses:1,vials=capacity?Math.floor(total/capacity):1,rest=capacity?total%capacity:0;if(vials>line.stock)return {error:'Insufficient '+item+' stock at '+branch};return {line,vials,rest,inventory:inventory.map(x=>x.id===line.id?{...x,uses:rest,used:x.used+vials,stock:x.stock-vials}:x)}}
const statusOf=(e,doses)=>e.remark==='Transferred'?'Transferred':e.rer?caseInfo(e,doses).status:'For RER'

export function Dashboard({branch,go,patients,encounters,doses,schedule,inventory,ledger,payments,finance,refunds,activity,can,userName}){
 const encs=encounters.filter(e=>!e.past&&inB(branch,encBranch(e))),todays=encs.filter(e=>e.date===today),dosesToday=doses.filter(d=>d.date===today&&inB(branch,d.branch)),sched=schedule.filter(s=>inB(branch,s.branch)),inv=scope(inventory,branch),pay=scope(payments,branch),fin=scope(finance,branch),month=today.slice(0,7)
 const sales=pay.filter(p=>p.date.startsWith(month)&&isSale(p)).reduce((a,x)=>a+x.amount,0),income=sales+fin.filter(f=>f.type==='Income'&&f.date.startsWith(month)).reduce((a,x)=>a+x.amount,0),expense=fin.filter(f=>f.type==='Expense'&&f.date.startsWith(month)).reduce((a,x)=>a+x.amount,0),statuses=encs.map(e=>caseInfo(e,doses).status)
 const seenToday=new Set([...todays.map(e=>e.patientId),...dosesToday.map(d=>encounters.find(e=>e.id===d.encounterId)?.patientId)]).size
 const metrics=[['Patients seen today',seenToday,Users,'teal',dosesToday.length+' doses administered today','patients'],['New admissions today',todays.length,ClipboardList,'blue','Registry numbers issued today','admissions'],['Vaccinations due today',sched.filter(s=>s.status==='Due today').length,CalendarDays,'amber',sched.filter(s=>s.status==='Missed').length+' missed follow-ups','schedule'],['Completed PEP series',statuses.filter(s=>s==='Complete').length,Syringe,'violet',statuses.filter(s=>s==='Ongoing').length+' treatments ongoing','patients'],['Low stock lines',inv.filter(x=>x.stock<=x.threshold).length,Package,'red','At or below branch threshold','alerts'],['Near expiry / expired',inv.filter(x=>x.expiry<addDays(today,60)).length,TriangleAlert,'amber','Within 60 days or past expiry','alerts'],['Sales this month',money(sales),CreditCard,'teal',pay.filter(p=>p.date===today).length+' transactions today','payments'],['Net balance this month',money(income-expense),PiggyBank,'blue','Income '+money(income)+' · Expenses '+money(expense),'finance'],['Refunds pending',refunds.filter(r=>inB(branch,r.branch)&&r.status==='Pending').length,FileText,'violet','Approval required','refunds']].filter(m=>can(m[5]))
 const counts=Object.entries(encs.reduce((a,e)=>({...a,[encBranch(e)]:(a[encBranch(e)]||0)+1}),{})).sort((a,b)=>b[1]-a[1]).slice(0,6)
 const animalCounts=['Dog','Cat','Others'].map(a=>[a,encs.filter(e=>e.animal===a).length])
 const cat=['I','II','III'].map(c=>encs.length?Math.round(encs.filter(e=>e.category===c).length/encs.length*100):0)
 const walkin=pay.length?Math.round(pay.filter(p=>p.classification==='Walk-in').length/pay.length*100):0
 const used=item=>ledger.filter(l=>l.item===item&&l.date>=addDays(today,-7)&&inB(branch,l.branch)).reduce((a,l)=>a+l.used,0)
 const year=today.slice(0,4)
 const trend=Array.from({length:12},(_,i)=>new Set(encs.filter(e=>e.date.startsWith(year+'-'+String(i+1).padStart(2,'0'))).map(e=>e.patientId)).size)
 const trendMax=Math.max(1,...trend)
 const clinicalView=can('patients')
 return <><SectionTitle eyebrow={longDate()} title={'Good morning, '+(userName||'there').split(' ')[0]} description={branch==='All branches'?'Here is what is happening across your clinic network today.':'Here is what is happening at '+branch+' branch today.'} action={<>{can('reports')&&<Button variant="secondary" icon={FileText} onClick={()=>go('reports')}>View reports</Button>}{can('admissions')&&<Button icon={Plus} onClick={()=>go('admissions')}>New admission</Button>}</>}/><div className="hero-banner"><div><div className="hero-eyebrow"><span className="live-dot"/> {branch==='All branches'?'NETWORK AT A GLANCE':branch.toUpperCase()+' BRANCH'}</div><h2>Care is moving forward.</h2><p>Track patients, follow-ups and branch operations from one connected workspace.</p>{can('schedule')?<button onClick={()=>go('schedule')}>Review today’s schedule <ArrowRight size={17}/></button>:<button onClick={()=>go('attendance')}>Open my attendance <ArrowRight size={17}/></button>}</div><div className="hero-visual"><span className="hero-ring ring-a"/><span className="hero-ring ring-b"/><span className="hero-center"><HeartPulse size={35}/></span><span className="hero-satellite sat-a"><Syringe size={18}/></span><span className="hero-satellite sat-b"><Users size={18}/></span><span className="hero-satellite sat-c"><Package size={18}/></span></div></div>{metrics.length>0&&<div className="stat-grid">{metrics.map(([label,value,Icon,tone,change,target])=><StatCard key={label} label={label} value={value} icon={Icon} tone={tone} change={change} onClick={()=>go(target,({'Patients seen today':'seen-today','New admissions today':'admissions-today','Vaccinations due today':'due-today','Completed PEP series':'complete','Near expiry / expired':'expiry','Refunds pending':'refunds-pending'})[label]||null)}/>)}</div>}
 {clinicalView?<><div className="dashboard-grid"><Card title={branch==='All branches'?'Patient volume by branch':'Cases by biting animal'} action={can('reports')&&<button className="text-link" onClick={()=>go('reports')}>Full report <ArrowRight size={14}/></button>}><div className="horizontal-bars">{(branch==='All branches'?counts:animalCounts).map(([name,n])=><div className="hbar-row" key={name}><span>{name}</span><Bar value={n} max={Math.max(1,...(branch==='All branches'?counts:animalCounts).map(x=>x[1]))}/><strong>{n}</strong></div>)}</div></Card><Card title="Monthly patient trend" action={<span className="subtle">Jan – Dec {year}</span>}><div className="vertical-chart">{trend.map((n,i)=><div className="chart-column" key={i}><span title={n+' patients'} style={{height:(n/trendMax)*100+'%'}}/><small>{['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</small></div>)}</div></Card><Card title="Exposure categories"><div className="donut-layout"><div className="donut" style={{background:`conic-gradient(#1c9c94 0 ${cat[0]}%,#6ea8d6 ${cat[0]}% ${cat[0]+cat[1]}%,#edb56d ${cat[0]+cat[1]}% 100%)`}}><span><b>{encs.length}</b><small>recorded cases</small></span></div><div className="legend"><div><i className="teal"/>Category I <strong>{cat[0]}%</strong></div><div><i className="blue"/>Category II <strong>{cat[1]}%</strong></div><div><i className="amber"/>Category III <strong>{cat[2]}%</strong></div></div></div></Card>{can('payments')?<Card title="Collection mix"><div className="mix-summary"><div><small>WALK-IN</small><strong>{walkin}%</strong></div><div><small>PHILHEALTH</small><strong>{100-walkin}%</strong></div></div><div className="mix-bar"><span style={{width:walkin+'%'}}/><span/></div><p className="card-note">Classification by recorded patient transactions.</p><div className="vaccine-mini"><strong>Stock used, last 7 days (vials)</strong><div><span>Bioshoot</span><Bar value={used('Bioshoot')} max={Math.max(1,used('Bioshoot'))}/><b>{used('Bioshoot')}</b></div><div><span>Tetanus</span><Bar value={used('Tetanus Toxoid')} max={Math.max(1,used('Bioshoot'))}/><b>{used('Tetanus Toxoid')}</b></div></div></Card>:<Card title="Stock used, last 7 days"><div className="vaccine-mini"><div><span>Bioshoot</span><Bar value={used('Bioshoot')} max={Math.max(1,used('Bioshoot'))}/><b>{used('Bioshoot')}</b></div><div><span>Tetanus</span><Bar value={used('Tetanus Toxoid')} max={Math.max(1,used('Bioshoot'))}/><b>{used('Tetanus Toxoid')}</b></div><div><span>Serum</span><Bar value={used('Serum')} max={Math.max(1,used('Bioshoot'))}/><b>{used('Serum')}</b></div></div><p className="card-note">Vials deducted from shift inventory ledgers.</p></Card>}</div>
 <div className="dashboard-lower">{can('schedule')&&<Card title="Upcoming vaccinations" action={<button className="text-link" onClick={()=>go('schedule')}>View schedule <ArrowRight size={14}/></button>}><div className="schedule-list">{sched.filter(s=>s.status!=='Missed').slice(0,4).map(s=><button key={s.id} onClick={()=>go('schedule')}><div className="date-chip"><strong>{s.date.slice(-2)}</strong><small>{fmt(s.date).slice(0,3).toUpperCase()}</small></div><div><strong>{s.patient}</strong><small>{dayLabel[s.day]} · {s.branch}</small></div><Badge>{s.status}</Badge></button>)}</div></Card>}<Card title="Recent activity" action={can('audit')&&<button className="text-link" onClick={()=>go('audit')}>Audit trail <ArrowRight size={14}/></button>}><div className="timeline">{(activity||[]).filter(a=>inB(branch,a.branch)).slice(0,4).map((a,i)=><div className="timeline-row" key={i}><span className="timeline-dot"/><div><strong>{a.title}</strong><small>{a.patient} · {a.branch}</small></div><time>{a.time}</time></div>)}</div></Card>{can('payments')&&<Card title="Recent transactions" action={<button className="text-link" onClick={()=>go('payments')}>View all <ArrowRight size={14}/></button>}><div className="simple-list">{pay.slice(0,4).map(p=><div key={p.id}><div><strong>{p.patient}</strong><small>{p.service} · {p.branch}</small></div><strong>{money(p.amount)}</strong></div>)}</div></Card>}</div>
 {branch==='All branches'&&<Card title="Branch comparison" action={can('branches')&&<button className="text-link" onClick={()=>go('branches')}>Manage branches <ArrowRight size={14}/></button>}><Table pageSize={6} columns={[{label:'BRANCH',render:r=><strong>{r.name}</strong>},{label:'CASES',key:'cases'},{label:'ADMISSIONS TODAY',key:'today'},{label:'DOSES GIVEN',key:'doses'},...(can('payments')?[{label:'COLLECTIONS',render:r=>money(r.collections)}]:[]),{label:'STATUS',render:()=> <Badge>Active</Badge>}]} rows={branches.slice(1).map(b=>({id:b,name:b,cases:encs.filter(e=>encBranch(e)===b).length,today:todays.filter(e=>e.branch===b).length,doses:doses.filter(d=>d.branch===b).length,collections:payments.filter(p=>p.branch===b).reduce((a,p)=>a+p.amount,0)})).sort((a,b)=>b.cases-a.cases)}/></Card>}</>
 :<Card title="Your workspace"><p className="card-note">Your role has access to the following modules. Clinical and financial data are hidden based on the approved permission matrix.</p><div className="row-actions margin-top">{['employees','attendance','payroll','payslips','reports'].filter(can).map(p=><button key={p} onClick={()=>go(p)}>{p[0].toUpperCase()+p.slice(1)}</button>)}</div></Card>}</>}

export function PatientsPage({branch,patients,setPatients,encounters,doses,schedule,go,setPatientId,notify,focus}){const [q,setQ]=React.useState(''),[status,setStatus]=React.useState(focus==='complete'?'Complete':''),[b,setB]=React.useState(''),[modal,setModal]=React.useState(false),[form,setForm]=React.useState(blankPatient(branch==='All branches'?'Guimba':branch));React.useEffect(()=>{setStatus(focus==='complete'?'Complete':'')},[focus]);const visible=patients.filter(p=>inB(branch,p.branch)||encounters.some(e=>e.patientId===p.id&&inB(branch,encBranch(e))));const doseByPatient={};doses.filter(d=>d.date===today&&inB(branch,d.branch)).forEach(d=>{const e=encounters.find(x=>x.id===d.encounterId);if(e)doseByPatient[e.patientId]=d});const seenIds=new Set([...encounters.filter(e=>!e.past&&e.date===today&&inB(branch,encBranch(e))).map(e=>e.patientId),...Object.keys(doseByPatient)]);const rows=visible.map(p=>{const e=latestOf(encounters,p.id),s=schedule.find(x=>x.patientId===p.id);return {...p,registry:e?.registry||'—',allRegistry:encounters.filter(x=>x.patientId===p.id).map(x=>x.registry).join(' '),last:e?.date,next:s?.date,status:e?statusOf(e,doses):'Registered',visits:encounters.filter(x=>x.patientId===p.id).length,doseToday:doseByPatient[p.id]}});const seen=focus==='seen-today';const filtered=rows.filter(p=>(!seen||seenIds.has(p.id))&&(!q||[p.name,p.first,p.middle,p.last,p.suffix,p.allRegistry,p.contact,p.id].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!status||p.status===status)&&(!b||p.branch===b));const open=p=>{setPatientId(p.id);go('profile')};const save=async()=>{if(!nameReady(form)){notify('Last name, first name, birthday, gender and cellphone are required');return}try{const p=await createPatientApi(form);setPatients([p,...patients]);setModal(false);setForm(blankPatient(form.branch));notify('Patient master record created')}catch(err){notify(err.message)}};return <><SectionTitle eyebrow="PATIENT MANAGEMENT" title="Patients" description={seen?'Admitted or given a saved dose on '+fmt(today)+'. The Today column is that dose.':focus==='complete'?'Completed PEP series. These are the finished cases counted on the dashboard.':'Reusable patient master records with visit history across authorized branches.'} action={<Button icon={Plus} onClick={()=>setModal(true)}>Register patient</Button>}/>{seen?<div className="summary-strip"><div><strong>{seenIds.size}</strong><span>Seen today</span></div><div><strong>{Object.keys(doseByPatient).length}</strong><span>Doses recorded</span></div><div><strong>{[...seenIds].filter(id=>!doseByPatient[id]).length}</strong><span>Admitted, no dose yet</span></div><div><button className="text-link" onClick={()=>go('patients')}>Show all patients</button></div></div>:focus==='complete'?<div className="summary-strip"><div><strong>{filtered.length}</strong><span>Completed PEP</span></div><div><button className="text-link" onClick={()=>go('patients')}>Show all patients</button></div></div>:<div className="summary-strip"><div><strong>{visible.length}</strong><span>Patient records</span></div><div><strong>{rows.filter(p=>p.status==='Ongoing').length}</strong><span>Ongoing PEP</span></div><div><strong>{rows.filter(p=>p.visits>1).length}</strong><span>Returning patients</span></div><div><strong>{rows.filter(p=>p.next===today).length}</strong><span>Due today</span></div></div>}<Card><div className="toolbar"><SearchBox value={q} onChange={setQ} placeholder="Search name, registry no. or contact number..."/>{branch==='All branches'&&<Select value={b} onChange={setB} options={branches.slice(1)} allLabel="All branches"/>}<Select value={status} onChange={setStatus} options={['For RER','Ongoing','Complete','Incomplete','No PEP','Transferred','Registered']} allLabel="All statuses"/></div><Table columns={[{label:'PATIENT / REGISTRY',render:r=><div className="table-person"><span className="person-avatar">{initials(r.name)}</span><span><strong>{r.name}</strong><small>{r.registry}</small></span></div>},{label:'AGE / SEX',render:r=>(ageFrom(r.birthday)||r.age)+' · '+r.sex},{label:'CELLPHONE',key:'contact'},{label:'ADDRESS',key:'address'},{label:'BRANCH',render:r=><span className="branch-pill">{r.branch}</span>},{label:'VISITS',key:'visits'},{label:'LAST VISIT',render:r=>fmt(r.last)},{label:'NEXT SCHEDULE',render:r=>fmt(r.next)},...(seen?[{label:'TODAY',render:r=>r.doseToday?<span><b>{dayLabel[r.doseToday.day]}</b><small className="block-sub">{r.doseToday.dose}</small></span>:<span>Admitted · no dose yet</span>}]:[]),{label:'STATUS',render:r=><Badge>{r.status}</Badge>},{label:'',render:()=> <span className="table-link">View →</span>}]} rows={filtered} onRowClick={open}/></Card>{modal&&<Modal title="Register patient" width="wide" onClose={()=>setModal(false)} footer={<><Button variant="secondary" onClick={()=>setModal(false)}>Cancel</Button><Button onClick={save}>Save patient</Button></>}><PatientFields form={form} setForm={setForm}/></Modal>}</>}

const bodySites=['Head','Upper extremity','Hand','Lower extremity','Foot']
const highRiskSites=new Set(['Head','Hand','Foot'])
const bodyPoints={
 Head:{L:[138,31],R:[114,31]},
 'Upper extremity':{L:[174,120],R:[78,120]},
 Hand:{L:[183,186],R:[64,186]},
 'Lower extremity':{L:[144,246],R:[108,246]},
 Foot:{L:[147,318],R:[100,318]}
}
function BodySitePicker({form,setForm}){const highRisk=highRiskSites.has(form.site),point=bodyPoints[form.site]?.[form.side||'L'];const selectSite=site=>setForm({...form,site,category:highRiskSites.has(site)?'III':form.category});return <div className="body-site-picker"><div className="form-section-title">Chief complaint / bite site</div><div className="body-site-layout"><div className="body-diagram" aria-label={form.site?`${form.side} ${form.site} selected`:'No body site selected'}><svg viewBox="0 0 460 360" role="img" aria-label="Front and back adult male whole-body diagram"><text className="body-view-label" x="115" y="358" textAnchor="middle">FRONT</text><text className="body-view-label" x="345" y="358" textAnchor="middle">BACK</text><text className="body-side-text" x="34" y="18">R</text><text className="body-side-text" x="196" y="18">L</text><image className="body-map-image" href={bodyMap} x="0" y="0" width="460" height="345" preserveAspectRatio="xMidYMid meet"/>{point&&<g className="body-marker"><circle cx={point[0]} cy={point[1]} r="13"/><circle cx={point[0]} cy={point[1]} r="5"/></g>}</svg><div className="body-selection">{form.site?<><b>{form.side} · {form.site}</b>{highRisk&&<span>Category III</span>}</>:<span>Select a body region to place the marker.</span>}</div></div><div className="body-site-controls"><Field label="Body region" value={form.site} options={bodySites} onChange={e=>selectSite(e.target.value)} required/><Choice label="Side" value={form.side} options={[['L','Left (L)'],['R','Right (R)']]} onChange={v=>setForm({...form,side:v})}/>{highRisk?<div className="body-category-rule"><strong>Category III applied automatically</strong><span>Head, hand, and foot are configured as Category III based on the confirmed clinic workflow.</span></div>:<p className="card-note">Selecting Head, Hand, or Foot automatically sets Category III. Other sites remain subject to clinic personnel assessment.</p>}<Field label="Chief complaint / notes" type="textarea" rows={3} value={form.chief} onChange={e=>setForm({...form,chief:e.target.value})} placeholder="Describe the bite, pain, swelling, or other complaint"/></div></div></div>}

function PatientFields({form,setForm,lockPhilhealth=false}){const set=(k,v)=>setForm({...form,[k]:v});return <><div className="form-section-title">Patient information (ARC admission form)</div><div className="form-grid"><Field label="Last name" value={form.last} onChange={e=>set('last',e.target.value)} required/><Field label="First name" value={form.first} onChange={e=>set('first',e.target.value)} required/><Field label="Middle name" value={form.middle} onChange={e=>set('middle',e.target.value)} help="Optional. Mother’s maiden surname."/><Field label="Suffix" value={form.suffix} options={suffixes} onChange={e=>set('suffix',e.target.value)} help="Leave blank if none."/><Field label="Cellphone No." value={form.contact} onChange={e=>set('contact',e.target.value)} required help="Required for follow-up contact."/><Field label="Birthday" type="date" value={form.birthday} onChange={e=>setForm({...form,birthday:e.target.value,senior:e.target.value?ageFrom(e.target.value)>=60:false})} required/><Field label="Age" value={form.birthday?ageFrom(form.birthday):''} disabled help="Computed from birthday"/><Field label="Gender" options={['Female','Male']} value={form.sex} onChange={e=>set('sex',e.target.value)} required/><Field label="Branch" options={branches.slice(1)} value={form.branch} onChange={e=>set('branch',e.target.value)}/><Field label="Address" value={form.address} onChange={e=>set('address',e.target.value)} placeholder="House no., barangay, municipality"/><Field label="Municipality / City (DOH report)" options={municipalities.map(m=>m[0]).concat('Others')} value={form.municipality} onChange={e=>setForm({...form,municipality:e.target.value,municipalityOther:e.target.value==='Others'?form.municipalityOther||'':''})} help="DOH catchment list. Choose Others if the patient lives outside these municipalities."/>{form.municipality==='Others'&&<Field label="Specify municipality / city" value={form.municipalityOther||''} onChange={e=>set('municipalityOther',e.target.value)} required placeholder="e.g. San Jose City"/>}</div><Field label="Name of Mother / Father / Guardian" value={form.guardian} onChange={e=>set('guardian',e.target.value)} help="Optional. A minor may sign consent if they can write their name."/><div className="form-section-title">Patient flags</div><div className="check-grid four">{[['Senior','senior'],['PWD','pwd'],['Vetmed','vetmed'],['PhilHealth','philhealth']].map(([l,k])=>{const lock=k==='philhealth'&&lockPhilhealth;return <Toggle key={k} label={l} checked={lock?false:form[k]} disabled={lock} onChange={v=>!lock&&set(k,v)}/>})}</div>{lockPhilhealth&&<p className="card-note">PhilHealth is off while <b>Pay now</b> is selected. Choose <b>For PhilHealth</b> if the patient is a member: no payment, give Day 0, then refer.</p>}</>}

